static async folders(
	repository: RecordRepository,
	commit: string,
	deadline: Deadline,
): Promise<Map<string, string>> {
	const root = await StateTree.#children(repository, commit, deadline);
	const folder = root.find(isChangesets);
	if (folder === undefined) return new Map();
	const entries = await StateTree.#children(repository, folder.oid, deadline);
	const seen = new Set<string>();
	const repeated = new Set<string>();
	for (const entry of entries) {
		const key = entry.path.toString("latin1");
		if (seen.has(key)) repeated.add(key);
		seen.add(key);
	}
	return new Map(
		entries.flatMap((entry) => {
			const name = repeated.has(entry.path.toString("latin1")) ? undefined : folderName(entry);
			return name === undefined ? [] : [[name, entry.oid] as const];
		}),
	);
}

// Throws `RecordError` `unknownFile` naming a stray that refuses calls on `changeset`: one in its folder, or outside every folder.
refuse(changeset: string): void {
	const stray = this.#strays[0] ?? this.#changesets.get(changeset)?.strays[0];
	if (stray !== undefined)
		throw new RecordError(
			"unknownFile",
			`${stray} on the record branch is no record or cell Melian wrote; a writer must remove it`,
			{ path: stray },
		);
}

it("is not blocked by a stray at the root, and leaves it", async () => {
	const store = await seeded();
	remote.plant({ "notes.txt": { bytes: "root" } });
	const seen = await store.folders();
	expect(await retireMerged(store, new Map([[changeset, seen.get(changeset)!]]))).toEqual(
		retirement({ removed: [changeset] }),
	);
	expect(remote.files().sort()).toEqual(["notes.txt", ...under(other)].sort());
	expect(remote.oid("notes.txt")).toBe(remote.git(["hash-object", "--stdin"], remote.path, { input: "root" }));
});

it("is not blocked by a file directly under `changesets/`, which is no folder, and leaves it", async () => {
	const store = await seeded();
	remote.plant({ "changesets/README": { bytes: "readme" } });
	const seen = await store.folders();
	expect(seen.has("README")).toBe(false);
	expect(await retireMerged(store, new Map([[changeset, seen.get(changeset)!]]))).toEqual(
		retirement({ removed: [changeset] }),
	);
	expect(remote.files()).toContain("changesets/README");
});

